-- Modelo físico del DER. Los nombres entre comillas conservan mayúsculas y tildes.
CREATE TABLE "Empresa" ("idEmpresa" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nombre varchar NOT NULL UNIQUE);
CREATE TABLE "Puesto" (codigo varchar PRIMARY KEY, nombre varchar NOT NULL, "descripción" varchar, activo boolean NOT NULL,
  "idEmpresa" bigint NOT NULL CONSTRAINT posee REFERENCES "Empresa");
CREATE TABLE "TipoCompetencia" ("idTipoCompetencia" varchar PRIMARY KEY, nombre varchar NOT NULL UNIQUE);
CREATE TABLE "Competencia" ("idCompetencia" bigint PRIMARY KEY, nombre varchar NOT NULL, descripcion varchar, activo boolean NOT NULL,
  "idTipoCompetencia" varchar NOT NULL CONSTRAINT clasifica REFERENCES "TipoCompetencia", tecnologia varchar, comportamiento varchar);
CREATE TABLE requiere (codigo varchar REFERENCES "Puesto", "idCompetencia" bigint REFERENCES "Competencia",
  "puntajeMinimo" double precision NOT NULL CHECK ("puntajeMinimo" BETWEEN 0 AND 10), PRIMARY KEY(codigo,"idCompetencia"));
CREATE TABLE "Factor" ("idFactor" bigint PRIMARY KEY, "idCompetencia" bigint NOT NULL CONSTRAINT agrupa REFERENCES "Competencia",
  nombre varchar NOT NULL, descripcion varchar, "nroOrden" integer, activo boolean NOT NULL);
CREATE TABLE "TipoPregunta" ("idTipoPregunta" varchar PRIMARY KEY, nombre varchar NOT NULL UNIQUE);
CREATE TABLE "Pregunta" ("idPregunta" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "idFactor" bigint NOT NULL CONSTRAINT contiene REFERENCES "Factor", "idTipoPregunta" varchar NOT NULL CONSTRAINT es_de_tipo REFERENCES "TipoPregunta",
  nombre varchar NOT NULL, enunciado varchar NOT NULL, descripcion varchar, activo boolean NOT NULL);
-- El CU021 permite seleccionar un conjunto existente y personalizar cada ponderación.
CREATE TABLE "PlantillaOpcion" ("idPlantilla" bigint PRIMARY KEY, "idTipoPregunta" varchar NOT NULL REFERENCES "TipoPregunta",
  texto varchar NOT NULL, puntaje double precision NOT NULL, orden integer NOT NULL, activo boolean NOT NULL);
CREATE TABLE "OpcionRespuesta" ("idOpcionRespuesta" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "idPregunta" bigint NOT NULL CONSTRAINT ofrece REFERENCES "Pregunta", "idPlantilla" bigint NOT NULL REFERENCES "PlantillaOpcion",
  texto varchar NOT NULL, puntaje double precision NOT NULL CHECK(puntaje>=0), orden integer NOT NULL, activo boolean NOT NULL,
  UNIQUE("idPregunta","idPlantilla"), UNIQUE("idPregunta","idOpcionRespuesta"));
CREATE TABLE "Consultor" ("idConsultor" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "nombreUsuario" varchar NOT NULL UNIQUE, contrasenia varchar, "tipoAcceso" varchar NOT NULL);
CREATE TABLE "RegistroAuditoria" ("idRegistroAuditoria" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "fechaHora" bigint NOT NULL, "detalleOperacion" varchar NOT NULL, "entidadAfectada" varchar NOT NULL,
  "idConsultor" bigint NOT NULL DEFAULT 1 CONSTRAINT controla REFERENCES "Consultor");
CREATE TABLE "Candidato" ("nroCandidato" integer PRIMARY KEY, apellido varchar NOT NULL, nombre varchar NOT NULL,
  "tipoDocumento" varchar NOT NULL, "nroDocumento" varchar NOT NULL, "fechaNacimiento" bigint, genero varchar, nacionalidad varchar,
  escolaridad varchar, email varchar, activo boolean NOT NULL, eliminado boolean NOT NULL, UNIQUE("tipoDocumento","nroDocumento"));
CREATE TABLE "Evaluacion" ("idEvaluacion" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  codigo varchar NOT NULL CONSTRAINT necesita REFERENCES "Puesto", fecha bigint NOT NULL, nombre varchar,
  "idConsultor" bigint NOT NULL DEFAULT 1 CONSTRAINT realiza REFERENCES "Consultor");
CREATE TABLE "ConfiguracionSistema" ("idConfiguracionSistema" bigint PRIMARY KEY, "instruccionesCuestionario" varchar NOT NULL,
  "tiempoMaximoMinutos" integer NOT NULL CHECK("tiempoMaximoMinutos">0), "cantidadAccesosMaximos" integer NOT NULL CHECK("cantidadAccesosMaximos">0));
CREATE TABLE "EstadoCuestionario" ("idEstadoCuestionario" varchar PRIMARY KEY, nombre varchar NOT NULL UNIQUE);
CREATE TABLE "Cuestionario" ("idCuestionario" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "idEvaluacion" bigint NOT NULL CONSTRAINT genera REFERENCES "Evaluacion", "nroCandidato" integer NOT NULL CONSTRAINT realiza REFERENCES "Candidato",
  clave varchar(8) UNIQUE NOT NULL, "fechaCreacion" bigint NOT NULL, "idEstadoCuestionario" varchar NOT NULL CONSTRAINT tiene REFERENCES "EstadoCuestionario",
  "fechaInicio" bigint, "fechaFin" bigint, "fechaCambioEstado" bigint, "ultimoIngreso" bigint,
  "cantAccesos" integer NOT NULL, posicion integer NOT NULL, "cantPreguntasPorFactor" integer NOT NULL DEFAULT 2 CHECK("cantPreguntasPorFactor">0),
  "cantPreguntasPorBloque" integer NOT NULL DEFAULT 2 CHECK("cantPreguntasPorBloque">0),
  "idConfiguracionSistema" bigint NOT NULL DEFAULT 1 CONSTRAINT usa REFERENCES "ConfiguracionSistema", UNIQUE("idEvaluacion","nroCandidato"));
CREATE UNIQUE INDEX un_cuestionario_abierto ON "Cuestionario"("nroCandidato") WHERE "idEstadoCuestionario" IN ('ACTIVO','EN_CURSO');
CREATE TABLE "BloqueCuestionario" ("idBloqueCuestionario" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "idCuestionario" bigint NOT NULL CONSTRAINT se_divide_en REFERENCES "Cuestionario", numero integer NOT NULL CHECK(numero>0),
  completado boolean NOT NULL DEFAULT false, "fechaCompletado" bigint, UNIQUE("idCuestionario",numero), UNIQUE("idCuestionario","idBloqueCuestionario"));
CREATE TABLE incluye ("idCuestionario" bigint NOT NULL, "ordenGlobal" integer NOT NULL, "idBloqueCuestionario" bigint NOT NULL,
  "ordenEnBloque" integer NOT NULL CHECK("ordenEnBloque">0), "idPregunta" bigint REFERENCES "Pregunta", "idFactor" bigint NOT NULL REFERENCES "Factor",
  enunciado varchar NOT NULL, PRIMARY KEY("idCuestionario","ordenGlobal"), UNIQUE("idBloqueCuestionario","ordenEnBloque"),
  UNIQUE("idCuestionario","ordenGlobal","idBloqueCuestionario"), FOREIGN KEY("idCuestionario","idBloqueCuestionario") REFERENCES "BloqueCuestionario"("idCuestionario","idBloqueCuestionario"));
CREATE TABLE "AlternativaEmitida" ("idCuestionario" bigint, "ordenGlobal" integer, "idPlantilla" bigint, texto varchar NOT NULL,
  puntaje double precision NOT NULL, orden integer NOT NULL, "idOpcionRespuesta" bigint REFERENCES "OpcionRespuesta",
  PRIMARY KEY("idCuestionario","ordenGlobal","idPlantilla"), FOREIGN KEY("idCuestionario","ordenGlobal") REFERENCES incluye);
CREATE TABLE "RespuestaCandidato" ("idRespuestaCandidato" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "idCuestionario" bigint NOT NULL, "ordenGlobal" integer NOT NULL, "idPlantilla" bigint NOT NULL, "fechaRespuesta" bigint,
  "idBloqueCuestionario" bigint NOT NULL CONSTRAINT registra REFERENCES "BloqueCuestionario",
  "idPregunta" bigint CONSTRAINT obtiene REFERENCES "Pregunta", "idOpcionRespuesta" bigint CONSTRAINT es_elegida REFERENCES "OpcionRespuesta",
  UNIQUE("idCuestionario","ordenGlobal"), FOREIGN KEY("idCuestionario","ordenGlobal","idPlantilla") REFERENCES "AlternativaEmitida",
  FOREIGN KEY("idCuestionario","ordenGlobal","idBloqueCuestionario") REFERENCES incluye("idCuestionario","ordenGlobal","idBloqueCuestionario"),
  FOREIGN KEY("idPregunta","idOpcionRespuesta") REFERENCES "OpcionRespuesta"("idPregunta","idOpcionRespuesta"));
CREATE TABLE "RegistroEjecucion" ("idRegistroEjecucion" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "idCuestionario" bigint NOT NULL CONSTRAINT actualiza REFERENCES "Cuestionario", accion varchar NOT NULL, "fechaHora" bigint NOT NULL, detalle varchar);
CREATE TABLE "Resultado" ("idResultado" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "idCuestionario" bigint NOT NULL UNIQUE CONSTRAINT genera REFERENCES "Cuestionario",
  "puntajeObtenido" double precision NOT NULL, "puntajeRequerido" double precision NOT NULL, activo boolean NOT NULL, cumplimiento boolean NOT NULL, "fechaCalculo" bigint);
CREATE TABLE "ResultadoCompetencia" ("idResultadoCompetencia" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "idResultado" bigint NOT NULL CONSTRAINT se_compone_de REFERENCES "Resultado", "idCompetencia" bigint NOT NULL CONSTRAINT mide REFERENCES "Competencia",
  "puntajeObtenido" double precision NOT NULL, "cumpleMinimo" boolean NOT NULL, UNIQUE("idResultado","idCompetencia"));
CREATE TABLE "ResultadoFactor" ("idResultadoFactor" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "idResultadoCompetencia" bigint NOT NULL CONSTRAINT detalla REFERENCES "ResultadoCompetencia", "idFactor" bigint NOT NULL CONSTRAINT aporta REFERENCES "Factor",
  "puntajeObtenido" double precision NOT NULL, UNIQUE("idResultadoCompetencia","idFactor"));

-- Proyecciones JDBC para los nombres de los campos que ya consumen los gestores Java.
CREATE VIEW app_competencia AS SELECT "idCompetencia" AS id,nombre,descripcion,activo,"idTipoCompetencia" AS tipo,tecnologia,comportamiento FROM "Competencia";
CREATE VIEW app_factor AS SELECT "idFactor" AS id,"idCompetencia" AS competencia,nombre,descripcion,"nroOrden" AS orden,activo FROM "Factor";
CREATE VIEW app_opcion AS SELECT "idPlantilla" AS id,"idTipoPregunta" AS tipo,texto,puntaje,orden,activo FROM "PlantillaOpcion";
CREATE VIEW app_pregunta AS SELECT "idPregunta" AS id,"idFactor" AS factor,"idTipoPregunta" AS tipo,nombre,enunciado,descripcion,activo FROM "Pregunta";
CREATE VIEW app_puesto AS SELECT p.codigo,p.nombre,p."descripción" AS descripcion,p.activo,e.nombre AS empresa FROM "Puesto" p JOIN "Empresa" e USING ("idEmpresa");
CREATE VIEW app_requisito AS SELECT codigo AS puesto,"idCompetencia" AS competencia,"puntajeMinimo" AS minimo FROM requiere;
CREATE VIEW app_candidato AS SELECT "nroCandidato" AS numero,apellido,nombre,"tipoDocumento" AS tipo_doc,"nroDocumento" AS documento,
 "fechaNacimiento" AS nacimiento,genero,nacionalidad,escolaridad,email,activo,eliminado FROM "Candidato";
CREATE VIEW app_evaluacion AS SELECT "idEvaluacion" AS id,codigo AS puesto,fecha,nombre FROM "Evaluacion";
CREATE VIEW app_auditoria AS SELECT "idRegistroAuditoria" AS id,"fechaHora" AS fecha,"detalleOperacion" AS detalle,"entidadAfectada" AS entidad FROM "RegistroAuditoria";
CREATE VIEW app_cuestionario AS SELECT "idCuestionario" AS id,"idEvaluacion" AS evaluacion,"nroCandidato" AS candidato,clave,"fechaCreacion" AS creado,
 "idEstadoCuestionario" AS estado,"fechaInicio" AS inicio,"fechaFin" AS fin,"ultimoIngreso" AS ultimo,"fechaCambioEstado","cantAccesos" AS accesos,posicion,
 "cantPreguntasPorFactor","cantPreguntasPorBloque","idConfiguracionSistema" FROM "Cuestionario";
CREATE VIEW app_item AS SELECT "idCuestionario" AS cuestionario,"ordenGlobal" AS orden,"idFactor" AS factor,enunciado,"idPregunta" FROM incluye;
CREATE VIEW app_alternativa AS SELECT "idCuestionario" AS cuestionario,"ordenGlobal" AS item,"idPlantilla" AS opcion,texto,puntaje,orden FROM "AlternativaEmitida";
CREATE VIEW app_respuesta AS SELECT "idCuestionario" AS cuestionario,"ordenGlobal" AS item,"idPlantilla" AS opcion FROM "RespuestaCandidato";
